window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-31bc077946d89053"]={"versions": [{"id": "FIG-31bc077946d89053", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd E2E_Receiver DE</code>) zur Darstellung des Empfängerablaufs auf Datenelement-Ebene (Data Element Level) innerhalb der AUTOSAR-Softwarearchitektur. Das Diagramm modelliert das Zusammenspiel zwischen einer empfangenden Software-Komponente, der AUTOSAR Runtime Environment (RTE) sowie den Basissoftware-Bibliotheken E2E Library und CRC Library.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien (Instanzen / Module):</p>\n<ul class=\"fig-list\"><li><code>Receiver of Data Elements</code>: Empfangende Software-Einheit bzw. Wrapper auf Datenelement-Ebene.\n</li><li><code>E2E Library</code>: E2E-Bibliotheksmodul zur Prüfung von E2E-Schutzdaten (Profile 1).\n</li><li><code>CRC Library</code>: CRC-Berechnungsmodul.\n</li><li><code>«module» RTE</code>: AUTOSAR Runtime Environment zur Bereitstellung der Datenkommunikation.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Signaturen:</p>\n<ul class=\"fig-list\"><li><code>Rte_Read_&lt;p&gt;_&lt;o&gt;(Instance, DataElement) : ret0</code>: Schnittstelle zum Lesen des Datenelements von der RTE.\n</li><li><code>E2E_P01Check(Config, State, Data) : ret</code>: Bibliotheksfunktion zur Prüfung der E2E-Header- und Nutzdaten anhand von Konfigurations- und Zustandsstrukturen.\n</li><li><code>Crc_CalculateCRCx(...)</code>: Aufruf zur zyklischen Redundanzprüfung für E2E-Profile 1 und 2.\n</li><li>Interne Variablen und Zustände: <code>Config</code>, <code>State</code> (mit Member <code>State.NewDataAvailable</code>), <code>DataElement</code>, <code>Data</code> (als <code>uint8*</code>-Array), <code>ret</code>, <code>ret0</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablaufsequenz:</p>\n<ol class=\"fig-list\"><li>Initialisierung: Beim Start des Empfängers (<code>[At Receiver startup]</code>) instanziiert und initialisiert <code>Receiver of Data Elements</code> die Strukturen <code>Config</code> und <code>State</code>.\n</li><li>Datenstatus: Die Empfangseinheit setzt <code>State.NewDataAvailable = TRUE</code>.\n</li><li>Datenabruf: Unter der Bedingung <code>[not invoked for 2nd channel of the wrapper]</code> ruft die Empfangseinheit synchron <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(Instance, DataElement)</code> an der <code>RTE</code> auf, welche den Rückgabewert <code>ret0</code> liefert.\n</li><li>Datenaufbereitung (<code>alt</code>-Block):\n<ul class=\"fig-list\"><li>Zweig <code>[allowed for any Data Element]</code>: Erzeugen des Arrays <code>Data</code> aus <code>DataElement</code> mit identischem Layout zur korrespondierenden I-PDU; Prüfung, dass alle ungenutzten High-Bits in <code>DataElement</code> auf 0 gesetzt sind.\n</li><li>Zweig <code>[for opaque arrays the implementer is allowed to use casting]</code>: Direkte Zeigerumwandlung über <code>Data = (uint8*) DataElement</code>.\n</li></ul>\n</li><li>E2E-Prüfung: Aufruf von <code>E2E_P01Check(Config, State, Data)</code> an der <code>E2E Library</code>.\n</li><li>Bibliotheksinterne Verarbeitung:\n<ul class=\"fig-list\"><li>Die E2E-Bibliothek führt Kontrollen der Steuerfelder durch (<code>Execute library logic, e.g. check all control fields</code>).\n</li><li>Für Profil 1 und 2 ruft sie synchron <code>Crc_CalculateCRCx</code> der <code>CRC Library</code> zur CRC-Berechnung auf.\n</li><li>Aktualisierung der Zustandsstruktur <code>State</code> abhängig von den Prüfungen (<code>update State depending on checks</code>).\n</li><li>Rückgabe des Prüfergebnisses <code>ret</code> an <code>Receiver of Data Elements</code>.\n</li></ul>\n</li><li>Auswertung und Konsum: Die Empfangseinheit wertet <code>ret</code> aus, behandelt eventuelle interne Bibliotheksfehler (<code>Evaluate ret and handle library internal errors</code>) und konsumiert das Datenelement (<code>Consume DataElement</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben und Integrationshinweise:</p>\n<ul class=\"fig-list\"><li>Datenlayout: Das Array <code>Data</code> muss exakt dem Layout der zugehörigen I-PDU entsprechen.\n</li><li>High-Bit-Konsistenz: Bei generischen Datenelementen ist zwingend sicherzustellen, dass nicht genutzte High-Bits mit Nullen belegt sind.\n</li><li>Type-Casting: Eine Umwandlung per Cast (<code>(uint8*)</code>) ist nur bei opaken Byte-Arrays implementierungsseitig zulässig.\n</li><li>Wrapper-Verhalten: Bei Mehrkanal-/Wrapper-Architekturen ist der Leseaufruf über die RTE für den zweiten Kanal zu unterdrücken.\n</li><li>Fehlerbehandlung: Der Rückgabewert <code>ret</code> der E2E-Bibliothek muss vor der Datenweiterverarbeitung explizit ausgewertet und auf interne Bibliotheksfehler geprüft werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5e97c87fc9767d6f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Empfängerablaufs auf Datenelement-Ebene (Data Element Level) innerhalb der AUTOSAR-Softwarearchitektur. Das Diagramm modelliert das Zusammenspiel zwischen einer empfangenden Software-Komponente, der AUTOSAR Runtime Environment (Rte) sowie den Basissoftware-Bibliotheken E2E Library und CRC Library.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien (Instanzen / Module):</p>\n<ul class=\"fig-list\"><li><code>Receiver of Data Elements</code>: Empfangende Software-Einheit bzw. Wrapper auf Datenelement-Ebene.\n</li><li><code>E2E Library</code>: E2E-Bibliotheksmodul zur E2E-Prüfung (Profile 1).\n</li><li><code>CRC Library</code>: CRC-Berechnungsmodul.\n</li><li><code>«module» Rte</code>: AUTOSAR Runtime Environment zur Bereitstellung der Datenkommunikation.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Signaturen:</p>\n<ul class=\"fig-list\"><li><code>Rte_IsUpdated_&lt;p&gt;_&lt;o&gt;(Instance)</code>: Abfrage der RTE zur Aktualität neuer Daten.\n</li><li><code>Rte_Read_&lt;p&gt;_&lt;o&gt;(Instance, DataElement) : ret0</code>: Schnittstelle zum Lesen des Datenelements von der RTE.\n</li><li><code>E2E_P01Check(Config, State, Data) : ret</code>: Bibliotheksfunktion zur E2E-Prüfung anhand von Konfigurations- und Zustandsstrukturen.\n</li><li><code>Crc_CalculateCRCx(...)</code>: Aufruf zur zyklischen Redundanzprüfung für E2E-Profile 1 und 2.\n</li><li>Interne Variablen und Zustände: <code>Config</code>, <code>State</code> (mit Member <code>State.NewDataAvailable</code>), <code>DataElement</code>, <code>Data</code> (als <code>(uint8*)DataElement</code>), <code>ret</code>, <code>ret0</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablaufsequenz:</p>\n<ol class=\"fig-list\"><li>Initialisierung: Beim Start des Empfängers (<code>[At Receiver startup]</code>) instanziiert und initialisiert <code>Receiver of Data Elements</code> die Strukturen <code>Config</code> und <code>State</code>.\n</li><li>Datenstatus: Die Empfangseinheit ruft <code>Rte_IsUpdated_&lt;p&gt;_&lt;o&gt;(Instance)</code> auf und weist das Ergebnis <code>State.NewDataAvailable</code> zu.\n</li><li>Datenabruf: Unter der Guard-Bedingung <code>[State.NewDataAvailable == TRUE]</code> ruft die Empfangseinheit synchron <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(Instance, DataElement)</code> an der <code>Rte</code> auf, welche den Rückgabewert <code>ret0</code> liefert.\n</li><li>Datenaufbereitung (<code>alt</code>-Block):\n<ul class=\"fig-list\"><li>Zweig <code>[allowed for any Data Element]</code>: Erzeugen des Arrays <code>Data</code> aus <code>DataElement</code> mit identischem Layout zur korrespondierenden I-PDU; Prüfung, dass alle ungenutzten High-Bits in <code>DataElement</code> auf 0 gesetzt sind.\n</li><li>Zweig <code>[for opaque arrays the implementer is allowed to use casting]</code>: Direkte Zeigerumwandlung über <code>Data = (uint8*)DataElement</code>.\n</li></ul>\n</li><li>E2E-Prüfung: Aufruf von <code>E2E_P01Check(Config, State, Data)</code> an der <code>E2E Library</code>.\n</li><li>Bibliotheksinterne Verarbeitung:\n<ul class=\"fig-list\"><li>Die E2E-Bibliothek prüft Steuerfelder (<code>Execute library logic, e.g. check all control fields</code>).\n</li><li>Für Profil 1 und 2 ruft sie synchron <code>Crc_CalculateCRCx</code> der <code>CRC Library</code> zur CRC-Berechnung auf.\n</li><li>Aktualisierung der Zustandsstruktur <code>State</code> abhängig von den Prüfungen (<code>update State depending on checks</code>).\n</li><li>Rückgabe des Prüfergebnisses <code>ret</code> an <code>Receiver of Data Elements</code>.\n</li></ul>\n</li><li>Auswertung und Konsum: Die Empfangseinheit wertet <code>ret</code> aus, behandelt eventuelle interne Bibliotheksfehler (<code>Evaluate ret and handle library internal errors</code>) und konsumiert das Datenelement (<code>Consume DataElement</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben und Integrationshinweise:</p>\n<ul class=\"fig-list\"><li>Datenabruf-Bedingung: Das Lesen des Datenelements via <code>Rte_Read</code> darf nur erfolgen, wenn die vorherige Überprüfung über <code>Rte_IsUpdated</code> signalisiert, dass neue Daten vorliegen (<code>State.NewDataAvailable == TRUE</code>).\n</li><li>Datenlayout: Das Array <code>Data</code> muss exakt dem Layout der zugehörigen I-PDU entsprechen.\n</li><li>High-Bit-Konsistenz: Bei generischen Datenelementen ist zwingend sicherzustellen, dass nicht genutzte High-Bits mit Nullen belegt sind.\n</li><li>Type-Casting: Eine Umwandlung per Cast (<code>(uint8*)</code>) ist nur bei opaken Byte-Arrays implementierungsseitig zulässig.\n</li><li>Fehlerbehandlung: Der Rückgabewert <code>ret</code> der E2E-Bibliothek muss vor der Datenweiterverarbeitung explizit ausgewertet und auf interne Bibliotheksfehler geprüft werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-31bc077946d89053", "to": "FIG-5e97c87fc9767d6f", "fr": "R3.2.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Diagrammrahmen: Entfall des UML-Rahmens <code>sd E2E_Receiver DE</code>.\n</li><li>RTE-Modulbezeichnung: Schreibweise von <code>«module» RTE</code> auf <code>«module» Rte</code> angepasst.\n</li><li>Abfrage der Datenverfügbarkeit: Ersetzung der statischen Zuweisung <code>State.NewDataAvailable = TRUE</code> durch den Funktionsaufruf <code>State.NewDataAvailable = Rte_IsUpdated_&lt;p&gt;_&lt;o&gt;(Instance)</code>.\n</li><li>Leseoperation der RTE: Die Ausführung von <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(Instance, DataElement) : ret0</code> steht nun unter der Guard-Bedingung <code>[State.NewDataAvailable == TRUE]</code> anstelle der Randbedingung <code>[not invoked for 2nd channel of the wrapper]</code>.\n</li><li>Typumwandlung: Entfernung eines Leerzeichens in der Typkonvertierung (<code>(uint8*) DataElement</code> zu <code>(uint8*)DataElement</code>).\n</li></ul>"}]};
